P(id='20261025-gamble-01', code='GAMBLE', sec=['CYBER','ECON'],
 title='กองปราบฯ ทลายเครือข่ายเว็บพนันออนไลน์ในชลบุรี จับ 8 ราย ขยายผลจากโรงงานผลิตบัญชีม้าพัทลุง ตามข้อกล่าวหา',
 agency='สื่อไทย > เดลินิวส์', origin='indirect', prio='B', sev='high', ver='media_only', stage='จับกุม', role='ปราบปรามเชิงรุก',
 prov=['ชลบุรี','พัทลุง'], alert=True, imp=False, units=['บก.ป.','บช.ก.','บก.ทล.','บก.รน.'],
 tags=['เว็บพนันออนไลน์','บัญชีม้า','ฟอกเงิน'], mo=['พนันออนไลน์','บัญชีม้า/ซิมม้า'], scale='ข้ามจังหวัด',
 pub='2026-10-24T13:57:00+07:00', src='https://www.dailynews.co.th/news/6301999/',
 corr=[('MGR Online','https://mgronline.com/crime/detail/9690000102537'),('ไทยรัฐ','https://www.thairath.co.th/news/crime/2968165'),('Thai Rath English','https://en.thairath.co.th/news/crime/2968165')],
 stats=dict(arrested=8,suspects=8,victims=None,loss_thb=None,seized_value_thb=42000),
 laws=['การกระทำผิดเกี่ยวกับการพนันทางสื่ออิเล็กทรอนิกส์','ฟอกเงิน','วัตถุออกฤทธิ์ต่อจิตประสาท ประเภท 2 (เคตามีน)'],
 pa=['อย่าให้ผู้อื่นยืมหรือเช่าบัญชีธนาคาร/ซิมการ์ดของตน แม้ได้รับค่าตอบแทน เพราะอาจถูกดำเนินคดีฐานเกี่ยวข้องกับการฟอกเงิน','ไม่กดลิงก์ชวนเล่นพนันออนไลน์ และแจ้งเบาะแสผ่านเว็บแจ้งความออนไลน์ thaipoliceonline.go.th หรือสายด่วน 1441 เมื่อพบการชักชวน'],
 ao=['ธนาคารควรเฝ้าระวังบัญชีที่มีธุรกรรมกระจายเป็นจำนวนมากในเวลาสั้นและตรวจสอบบัญชีที่เปิดใหม่เป็นชุด','ผู้ให้บริการแพลตฟอร์มชำระเงินควรทบทวนมาตรการยืนยันตัวตนของร้านค้าที่รับชำระเงินจากเว็บพนัน'],
 op='ปฏิบัติการ “ทลายเครือข่ายเว็บพนันออนไลน์” ตรวจค้น 9 จุดในจังหวัดชลบุรี', outcome='จับกุม', note='ขยายผลจากปฏิบัติการ “เสียงกระซิบจากศรีบรรพต” (ม.ค. 2569) ที่ทลายโรงงานผลิตบัญชีม้า อ.เมือง จ.พัทลุง',
 content='เดลินิวส์ มติชน MGR Online และไทยรัฐรายงานตรงกันว่า เมื่อวันที่ 24 ตุลาคม 2569 กองบังคับการปราบปราม (บก.ป.) สังกัด บช.ก. สนธิกำลังกับ กก.2 บก.ป., ส.ทล.1 กก.8 บก.ทล. และ ส.รน.1 กก.5 บก.รน. เปิดปฏิบัติการทลายเครือข่ายเว็บพนันออนไลน์ ตรวจค้น 9 จุดในพื้นที่จังหวัดชลบุรี จับกุมผู้ต้องหา 8 ราย เป็นชาย 6 หญิง 2 โดย 7 รายถูกจับตามหมายจับศาลอาญาในข้อกล่าวหาร่วมกันจัดให้มีการเล่น ช่วยประกาศโฆษณา หรือชักชวนให้ผู้อื่นเล่นพนันทางสื่ออิเล็กทรอนิกส์ และสมคบกันฟอกเงิน อีก 1 รายถูกแจ้งข้อหามีวัตถุออกฤทธิ์ประเภท 2 (เคตามีน) ไว้เพื่อจำหน่าย ตามที่ตำรวจแถลง คดีนี้สืบเนื่องจากเมื่อเดือนมกราคม 2569 บก.ป. เปิดปฏิบัติการ “เสียงกระซิบจากศรีบรรพต” ทลายโรงงานผลิตบัญชีม้าใน อ.เมือง จ.พัทลุง ซึ่งผู้ต้องหาระดับสั่งการถูกกล่าวหาว่าหลอกชาวบ้านให้เปิดบัญชีม้า มีผู้เสียหายแจ้งความออนไลน์จำนวนมาก การสืบสวนขยายผลพบว่าบัญชีม้าเหล่านั้นถูกนำไปใช้ทั้งในการหลอกลวงประชาชนและในกิจการเว็บพนันออนไลน์ เจ้าหน้าที่จึงขออนุมัติหมายจับเครือข่ายเว็บพนัน ของกลางที่ตรวจยึดได้ประกอบด้วยคอมพิวเตอร์ 2 เครื่อง โทรศัพท์มือถือ 14 เครื่อง สมุดบัญชีธนาคาร 10 เล่ม บัตร ATM 19 ใบ เงินสด 42,000 บาท และยาเคตามีนจำนวนหนึ่ง ผลการสอบสวนเบื้องต้นระบุว่าผู้ต้องหาบางรายให้การรับสารภาพ แต่บางรายยังให้การปฏิเสธ ตำรวจส่งตัวผู้ต้องหาและของกลางให้พนักงานสอบสวน กก.6 บก.ป. ดำเนินคดีตามกฎหมาย ทั้งนี้ ผู้ต้องหาทุกรายยังถือเป็นผู้บริสุทธิ์จนกว่าศาลจะมีคำพิพากษา ข่าวนี้สะท้อนรูปแบบที่ตำรวจเรียกว่าห่วงโซ่เศรษฐกิจใต้ดิน คือบัญชีม้าที่ผลิตเป็นชุดป้อนทั้งแก๊งสแกมเมอร์และเว็บพนัน ทำให้การตัดต้นทางด้วยการจับกุมผู้จัดหาบัญชีและผู้รับจ้างเปิดบัญชีมีผลต่อการลดความเสียหายในหลายคดีพร้อมกัน ประชาชนที่ถูกชักชวนให้ขายหรือให้เช่าบัญชีควรตระหนักว่าอาจมีความผิดฐานช่วยเหลือการฟอกเงิน')

P(id='20261025-cyber-01', code='CYBER', sec=['ECON'],
 title='ตำรวจทางหลวงดักจับผู้ต้องหาตามหมายจับ เครือข่ายฟอกเงินแก๊งคอลเซ็นเตอร์ผ่านแอปซื้อขายทองคำ เสียหายกว่า 8 ล้านบาท ที่นครสวรรค์',
 agency='สื่อไทย > MGR Online', origin='indirect', prio='B', sev='high', ver='single_source', stage='จับกุม', role='สืบสวนจับกุม',
 prov=['นครสวรรค์','กรุงเทพมหานคร'], alert=True, imp=False, units=['บก.ทล.','ศกค.ตร.','สน.ทุ่งมหาเมฆ'],
 tags=['ฟอกเงินผ่านทองคำ','แก๊งคอลเซ็นเตอร์','บัญชีม้า'], mo=['คอลเซ็นเตอร์','ฟอกเงิน'], scale='ระดับชาติ',
 pub='2026-10-24T21:13:00+07:00', src='https://mgronline.com/crime/detail/9690000102539', corr=[],
 stats=dict(arrested=1,suspects=1,victims=None,loss_thb=8000000,seized_value_thb=None),
 laws=['ฉ้อโกงประชาชน','นำเข้าข้อมูลคอมพิวเตอร์อันเป็นเท็จ','อั้งยี่ ซ่องโจร','ฟอกเงิน'],
 pa=['หากถูกอ้างเป็นเจ้าหน้าที่แล้วให้โอนเงินเพื่อ “ตรวจสอบ” ให้หยุดและวางสาย ตรวจสอบกับหน่วยงานผ่านช่องทางทางการเท่านั้น','ผู้เสียหายจากการโอนเงินให้แจ้งอายัดบัญชีทันทีผ่านสายด่วน 1441 หรือเว็บ thaipoliceonline.go.th'],
 ao=['ร้านค้าทองและแพลตฟอร์มซื้อขายทองออนไลน์ควรกำหนดเกณฑ์ตรวจสอบคำสั่งซื้อที่เกิดจากเงินโอนหลายบัญชีและรับทองหน้าร้านปริมาณสูง','ธนาคารควรแบ่งปันข้อมูลบัญชีม้ากับศูนย์ประสานงานของตำรวจให้รวดเร็ว'],
 op='สกัดจับผู้ต้องหาตามหมายจับริมทางหลวง 3004 จ.นครสวรรค์', outcome='จับกุม', note='ได้เบาะแสจากศูนย์บริหารเหตุการณ์แก๊งคอลเซ็นเตอร์และค้ามนุษย์นานาชาติ (ศกค.) หรือ Warroom ตร.',
 content='MGR Online รายงานว่า เมื่อวันที่ 24 ตุลาคม 2569 พล.ต.ต.บุญลือ ผดุงถิ่น ผบก.ทล. สั่งการให้ชุดสืบสวน กก.1 บก.ทล. จับกุมชายวัย 46 ปีรายหนึ่ง ซึ่งเป็นผู้ต้องหาตามหมายจับศาลอาญากรุงเทพใต้ที่ 574/2569 ลงวันที่ 12 พฤษภาคม 2569 ข้อหาร่วมกันฉ้อโกงประชาชน ร่วมกันนำเข้าข้อมูลอันเป็นเท็จเข้าสู่ระบบคอมพิวเตอร์ อั้งยี่ ซ่องโจร และร่วมกันฟอกเงิน โดยจับกุมได้ริมถนนทางหลวงหมายเลข 3004 ต.หนองปลิง อ.เมือง จ.นครสวรรค์ ตามข้อมูลที่ตำรวจแถลง ศูนย์บริหารเหตุการณ์แก๊งคอลเซ็นเตอร์และค้ามนุษย์นานาชาติ (ศกค.) หรือ Warroom ตร. ได้รับเบาะแสว่ามีขบวนการหลอกลวงผู้เสียหายให้โอนเงินเข้าบัญชีม้า แล้วนำเงินไปฟอกด้วยการสั่งซื้อทองคำผ่านแอปพลิเคชันซื้อขายทองคำออนไลน์ เพื่อแปลงเป็นทองคำแท่งส่งให้แก๊งคอลเซ็นเตอร์ข้ามชาติ มูลค่าความเสียหายรวมกว่า 8 ล้านบาท จากการติดต่อขอรับทองคำแท่งน้ำหนักรวม 120 บาท 3 สลึง โดยเริ่มดำเนินการตั้งแต่เดือนกุมภาพันธ์ 2569 กลุ่มผู้ต้องหาเข้าติดต่อรับทองที่ร้านทองชื่อดังสาขาเยาวราชและสีลม รวม 4 ครั้ง ได้ทองน้ำหนักรวม 90 บาท 3 สลึง ต่อมามีการไปรับทองที่สาขาเยาวราชอีกครั้ง แล้วนำไปส่งมอบให้นายทุนในห้องน้ำชายของศูนย์การค้าใกล้เคียง เพื่อหลบกล้องวงจรปิด ตำรวจเข้าจับกุมผู้ต้องหาส่วนหนึ่งขณะติดต่อขอรับทองคำ 30 บาทที่สาขาสีลม แล้วขยายผลจนทราบว่าผู้ต้องหาที่หลบหนีรายนี้จะเดินทางผ่านนครสวรรค์ จึงกระจายกำลังเฝ้าสกัดและจับกุมได้ ผู้ต้องหาให้การปฏิเสธตลอดข้อกล่าวหา ตำรวจควบคุมตัวส่งพนักงานสอบสวน สน.ทุ่งมหาเมฆ ดำเนินคดีต่อไป ข่าวนี้แสดงรูปแบบการฟอกเงินด้วยทองคำแท่งที่ตรวจสอบย้อนกลับได้ยากกว่าการโอนเงิน และเป็นตัวอย่างของการประสานข้อมูลระหว่างศูนย์ต่อต้านแก๊งคอลเซ็นเตอร์ ตำรวจทางหลวง และตำรวจพื้นที่ ผู้ต้องหายังถือเป็นผู้บริสุทธิ์จนกว่าศาลจะพิพากษา')

